using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and rhetoric." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and their significance." }
        };

        _courses = new List<Course>
        {
            new()
            {
                Id = 1, Code = "CS 101", Title = "Introduction to Programming",
                Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science",
                InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published research on CS pedagogy.",
                IsFeatured = true
            },
            new()
            {
                Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms",
                Description = "Study of fundamental data structures (lists, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", DepartmentId = 1, DepartmentName = "Computer Science",
                InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez specializes in algorithm optimization and holds multiple patents in search technologies.",
                IsFeatured = true
            },
            new()
            {
                Id = 3, Code = "CS 310", Title = "Database Systems",
                Description = "Design and implementation of relational databases. Covers SQL, normalization, indexing, and transaction management.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", DepartmentId = 1, DepartmentName = "Computer Science",
                InstructorName = "Dr. Carol Williams", InstructorBio = "Dr. Williams worked as a database architect at major tech firms before joining academia."
            },
            new()
            {
                Id = 4, Code = "MATH 101", Title = "Calculus I",
                Description = "Introduction to differential calculus. Limits, derivatives, and applications of differentiation.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, DepartmentName = "Mathematics",
                InstructorName = "Dr. David Park", InstructorBio = "Dr. Park is a renowned mathematician who has authored three widely-used calculus textbooks.",
                IsFeatured = true
            },
            new()
            {
                Id = 5, Code = "MATH 201", Title = "Linear Algebra",
                Description = "Vector spaces, linear transformations, matrices, eigenvalues, and applications.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentId = 2, DepartmentName = "Mathematics",
                InstructorName = "Dr. Elena Rossi", InstructorBio = "Dr. Rossi's research focuses on applied linear algebra in machine learning."
            },
            new()
            {
                Id = 6, Code = "MATH 301", Title = "Probability and Statistics",
                Description = "Introduction to probability theory, random variables, distributions, and statistical inference.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, DepartmentName = "Mathematics",
                InstructorName = "Dr. Frank Thompson", InstructorBio = "Dr. Thompson consults for healthcare organizations on statistical modeling."
            },
            new()
            {
